use std::collections::BinaryHeap;

fn delete(h: &mut BinaryHeap<i64>, del: &mut BinaryHeap<i64>) {
    while !del.is_empty() {
        let a = *h.peek().unwrap();
        let b = *del.peek().unwrap();
        if a == b {
            h.pop();
            del.pop();
        } else {
            break;
        }
    }
}

fn run() {
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    input! {
        n: usize,
        q: usize,
        a: [i64; 2 * n],
        b: [i64; 2 * n],
        p: [(usize1, i64, i64); q],
    }
    let mut a = a;
    let mut b = b;
    let mut sum = a.iter().fold(0, |s, a| s + *a);
    let mut small = BinaryHeap::new();
    let mut small_del = BinaryHeap::new();
    let mut large = BinaryHeap::new();
    let mut large_del = BinaryHeap::new();
    let mut large_sum = 0;
    for i in 1..(2 * n - 1) {
        let v = b[i] - a[i];
        if v <= 0 {
            small.push(v);
        } else {
            large.push(-v);
            large_sum += v;
        }
    }
    for (p, x, y) in p {
        if 0 < p && p < 2 * n - 1 {
            let v = b[p] - a[p];
            if v <= 0 {
                small_del.push(v);
            } else {
                large_del.push(-v);
                large_sum -= v;
            }
            let v = y - x;
            if v <= 0 {
                small.push(v);
            } else {
                large.push(-v);
                large_sum += v;
            }
        }
        sum -= a[p];
        sum += x;
        a[p] = x;
        b[p] = y;
        delete(&mut small, &mut small_del);
        delete(&mut large, &mut large_del);
        let ans = if (large.len() - large_del.len()) % 2 == 0 {
            sum + large_sum
        } else {
            let a = *small.peek().unwrap();
            let b = -*large.peek().unwrap();
            sum + (large_sum - b) + std::cmp::max(0, a + b)
        };
        writeln!(out, "{}", ans).ok();
    }
}

