fn polymod(a: Vec<i32>, mut b: Vec<i32>) -> Vec<i32> {
    if a.len() > b.len() {
        return b;
    }
    let al = a.len();
    let bl = b.len();
    assert!(a[0] == 1 && b[0] == 1);

    for i in 0..bl-al+1 {
        if b[i] == 1 {
            for j in 0..al {
                b[i+j] ^= a[j];
            }
        }
    }

    let mut res = vec![];
    for i in bl-al+1..bl {
        if b[i] == 1 {
            for j in i..bl {
                res.push(b[j]);
            }
            break;
        }
    }
    res
}

fn polygcd(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    if b.len() == 0 {
        return a;
    } else {
        let bb = b.clone();
        polygcd(bb, polymod(b, a))
    }
}

