    let mut c = 0;
    let mut num = w[0];
    for i in 0..w.len() {
        let x = w[i];
        if x == num {
            c += 1;
        } else {
            if counts.insert(num, (c, counts_vec.len() + 1)) != None {
                println!("0");
                return;
            }
            counts_vec.push((num,c));
            c = 1;
            num = x;
        }
    }
    if counts.insert(num, (c, counts_vec.len() + 1)) != None {
        println!("0");
        return;
