    counts_vec.push((num,c));
    counts_vec.insert(0, (num,c));
    let t = counts_vec[1];
    counts_vec.push(t);

    if w.iter().all(|x| *x == 1) {
        println!("{}", (1..n+1).fold(1, |ac, x| ac * x % d));
        return;
