        println!("0");
        return;
    }

    let mut ans = 1;
    let mut lsum = 0;
    let mut p = 0;
    for m in 1..n+1 {
        if let Some(x) = counts.get(&m) {
            let (c, i) = *x;
            if c > len {
                println!("0");
                return;
            }
