type Graph = Vec<Vec<usize>>;

fn find_pair(g: &Graph) -> (usize, usize) {
    let (u, _) = dfs(0, None, g);
    let (v, _) = dfs(u, None, g);
    (u, v)
}

fn dfs(now: usize, par: Option<usize>, g: &Graph) -> (usize, i32) {
    let mut best = (now, 0);
    for &to in &g[now] {
        if Some(to) == par {
            continue;
        }
        let (r, t) = dfs(to, Some(now), g);
        if best.1 < t+1 {
            best = (r, t+1);
        }
    }
    best
}

fn dfsp(now: usize, par: Option<usize>, g: &Graph, parent: &mut Vec<Option<usize>>) {
    parent[now] = par;
    for &to in &g[now] {
        if Some(to) == par {
            continue;
        }
        dfsp(to, Some(now), g, parent);
    }
}

fn make(line: Vec<usize>, g: &Graph) -> Vec<usize> {
    let ln = line.len();
    let n = g.len();
    let mut w = vec![];
    let mut now = 1;
    for i in 0..ln {
        if 1 <= i && i <= ln-2 {
            let child = g[line[i]].len()-2;
            for c in 1..child+1 {
                w.push(now+c);
            }
            w.push(now);
            now += 1;
            now += child;
        } else {
            w.push(now);
            now += 1;
            assert!(g[line[i]].len() == 1);
        }
    }
    w
}


fn main() {
    input! {
        n: usize,
        edges: [(usize1, usize1); n-1]
    };

    let mut g = vec![vec![]; n];
    for (u, v) in edges {
        g[u].push(v);
        g[v].push(u);
    }
    let (mut f, mut t) = find_pair(&g);
    let mut parent = vec![None; n];
    dfsp(f, None, &g, &mut parent);

    let mut line = vec![];
    {
        let mut now = t;
        while let Some(p) = parent[now] {
            line.push(now);
            now = p;
        }
        line.push(f);
    }
    line.reverse();
    let ln = line.len();


    {
        let mut mark = vec![false; n];
        for i in 0..ln {
            let v = line[i];
            for &to in &g[v] {
                mark[to] = true;
            }
            mark[v] = true;
        }
        let mut ok = true;
        for i in 0..n {
            if !mark[i] {
                ok = false;
                break;
            }
        }
        if !ok {
            println!("-1");
            return;
        }
    }

    let w0 = make(line.clone(), &g);
    line.reverse();
    let w1 = make(line, &g);

    println!("{}", join!(min(w0, w1), " "));
}

