        let (mut p, mut s) = (0u64, 0u64);
        for j in 1..(k+1) {
            if 2*j == t { continue; }
            if  1 <= t-j && t-j <= k {
                p += 1;
            } else {
                s += 1;
            }
        }
        p /= 2;

        let mut p2 = M::new(1);
        for q in 0..(p+1) {
            let n = n as u64;
            if q > n { break; }
            if q == 0 && s == 0 { continue; }
            let x = c.comb(p, p-q);
            let y = c.comb(n+s-1, q+s-1);
            ans += x * y * p2;
            if t % 2 == 0 && q < n {
                let y = c.comb(n+s-2, q+s-1);
                ans += x * y * p2;
            }
            p2 *= 2;
        }
        println!("{}", ans.0);
    }

