    let (s1, s2) = (s1.as_bytes(), s2.as_bytes());
    let (c1, c2) = (s1[0], s2[0]);
    if c1 > c2 {
        '>'
    } else if c1 < c2 {
        '<'
    } else {
        '='
    }
}


