fn solve(edges: Vec<Vec<usize>>, nodes: usize) {
    let mut is_used: Vec<bool> = vec![false; nodes];
    let mut lowlink: Vec<usize> = vec![1000000000; nodes];
    let mut orders: Vec<usize> = vec![0; nodes];
    let mut order = 0;
    let mut is_dfs_edge: Vec<_> = edges.iter().map(|es| vec![false; es.len()]).collect();
    let mut dfs_stack = vec![];
    let mut bridges = vec![];
    fn min(x: usize, y: usize) -> usize {
        if x < y {
            x
        } else {
            y
        }
    }
    fn max(x: usize, y: usize) -> usize {
        if x < y {
            y
        } else {
            x
        }
    }

    for i in 0..nodes {
        if is_used[i] {
            continue;
        }
        dfs_stack.push(i);
        // Root node
        'outer: while !dfs_stack.is_empty() {
            let node = *dfs_stack.last().unwrap();
            if !is_used[node] {
                is_used[node] = true;
                orders[node] = order;
                lowlink[node] = order;
                order += 1;
            }
            for (idx, &to) in edges[node].iter().enumerate() {
                if !is_used[to] {
                    // DFS.
                    dfs_stack.push(to);
                    is_dfs_edge[node][idx] = true;
                    continue 'outer;
                }
            }
            let last = dfs_stack.pop().unwrap();
            let parent = *dfs_stack.last().unwrap_or(&10000000);
            for (&to, &is_dfs) in edges[last].iter().zip(is_dfs_edge[node].iter()) {
                if to == parent {
                    continue;
                } else if is_dfs {
                    let low = lowlink[to];
                    lowlink[last] = min(lowlink[last], low);
                } else {
                    lowlink[last] = min(lowlink[last], orders[to]);
                }
                if orders[last] < lowlink[to] {
                    let from = min(last, to);
                    let to = max(last, to);
                    bridges.push((from, to));
                }
            }
        }
    }
    bridges.sort();
    for (s, t) in bridges {
        println!("{} {}", s, t);
    }
}

