fn solve() {
    input!{
        N:usize,
        s:chars,
    }

    let mut dp=vec![0;N];

    // 1個目で小さい方からk個のやつをとる場合の数は全部1
    for k in 0..N {
        dp[k]=1;
    }

    for i in 1..N { // i番目を埋める
        let m = N-i; // 残りの個数
        let mut cum = CumSum1::build(&dp);
        if s[i-1] == '<' {
            for k in 0..m {
                dp[k] = cum.query(0,k+1);
            }
        } else {
            for k in 0..m {
                dp[k] = cum.query(k+1,m+1);
            }
        }
    }
    println!("{}", dp[0]);
}

struct CumSum1 {
    dp: Vec<i64>,
}
impl CumSum1 {
    fn build(base: &[i64]) -> CumSum1 {
        let n = base.len();
        let mut dp = vec![0; n+1];
        let mut acc = 0;
        for i in 0..n {
            acc += base[i];
            acc %= mo;
            dp[i+1] = acc;
        }
        CumSum1 {
            dp: dp,
        }
    }
    // [i,j)
    fn query(&self, i: usize, j: usize) -> i64 {
        (mo + self.dp[j] - self.dp[i]) % mo
    }
}

