    let mut tree: Vec<Vec<usize>> = vec![Vec::new(); n];
    let mut parent_dict: HashMap<usize, usize> = HashMap::new();
    make_tree(root, n, &edges, &mut tree, &mut parent_dict);

    let mut rank = 1;
    let mut pointer = n - 1;
    let mut color = vec![0; n]; // 0: uncolored, 1: black, 2: white
    while pointer != 0 {
        rank += 1;
        pointer = parent_dict[&pointer];
    }
    let mut pointer = n - 1;
    for i in 0..rank {
        if i < rank / 2 {
            color[pointer] = 2;
        } else {
            color[pointer] = 1;
        }
        if i == rank - 1 {
            break;
        }
        pointer = parent_dict[&pointer];
    }

    let mut topological_sorted_indexes = vec![root];
    topological_dfs(root, &tree, &mut topological_sorted_indexes);
    // debug!(topological_sorted_indexes);

    for idx in topological_sorted_indexes {
        for &child_idx in edges[idx].iter() {
            if color[child_idx] == 0 {
                color[child_idx] = color[idx];
            }
        }
    }
    // debug!(color);
    let mut black_count = 0;
    let mut white_count = 0;
    for i in 0..n {
        if color[i] == 1 {
            black_count += 1;
        } else if color[i] == 2 {
            white_count += 1;
        }
    }

    assert!(black_count + white_count == n);
    if white_count >= black_count {
        println!("Snuke");
    } else {
        println!("Fennec");
    }
}

fn make_tree(
    cur_idx: usize,
    parent_idx: usize,
    edges: &Vec<Vec<usize>>,
    tree: &mut Vec<Vec<usize>>,
    parent_dict: &mut HashMap<usize, usize>,
) {
    for child_idx in edges[cur_idx].iter() {
        if *child_idx == parent_idx {
            continue;
        }
        tree[cur_idx].push(*child_idx);
        parent_dict.insert(*child_idx, cur_idx);
        make_tree(*child_idx, cur_idx, edges, tree, parent_dict);
    }
}

fn topological_dfs(cur_idx: usize, tree: &Vec<Vec<usize>>, result: &mut Vec<usize>) {
    for child_idx in tree[cur_idx].iter() {
        result.push(*child_idx);
        topological_dfs(*child_idx, tree, result);
    }
}

