const INF: usize = 1_000_000_000_000_000;

fn lower_bound<F>(l: isize, r: isize, criterion: F) -> isize
where
    F: Fn(isize) -> bool,
{
    let mut l = l;
    let mut r = r;
    while r - l > 1 {
        let mid = l + (r - l) / 2;
        if criterion(mid) {
            r = mid;
        } else {
            l = mid;
        }
    }
    r
}

fn dfs(
    node: usize,
    parent: usize,
    nodes: &Vec<Vec<usize>>,
    dp: &mut Vec<usize>,
    res: &mut Vec<usize>,
    a: &Vec<usize>,
    mut val: usize,
) {
    let crit = |i: isize| {
        let i = i as usize;
        a[node - 1] <= dp[i]
    };
    let i = lower_bound(-1, a.len() as isize, crit) as usize;
    if dp[i] == INF {
        val += 1;
    }
    let before = dp[i];
    dp[i] = a[node - 1];
    for &next in &nodes[node] {
        if next == parent {
            continue;
        }
        dfs(next, node, nodes, dp, res, a, val);
    }
    dp[i] = before;
    res[node - 1] = val;
}

