    let mut nodes = vec![Vec::new(); n + 1];
    for (u, v) in uv {
        nodes[u].push(v);
        nodes[v].push(u);
    }

    let mut res = vec![0; n];
    dfs(1, 0, &nodes, &mut vec![INF; n], &mut res, &a, 0);
    for i in 0..n {
        println!("{}", res[i]);
    }
}

