fn list_divisors(mut n: u64) -> Vec<u64> {
    let mut divisors = vec![1];
    let mut sqrt = ((n - 1) as f64).sqrt() as u64 + 1;
    let sieve_len = (sqrt - 1) as usize / 2;
    let mut sieve = vec![0u64; (sieve_len.saturating_sub(1)) / 64 + 1];
    let mut f = 2;
    let mut si = 0;
    while n > 1 {
        let (mut beg, len) = (0, divisors.len());
        while n % f == 0 {
            n /= f;
            sqrt = (n as f64).sqrt() as u64;
            for i in beg..beg + len {
                let t = divisors[i];
                divisors.push(t * f);
            }
            beg += len;
        }
        while si < sieve_len && (sieve[si / 64] & 1 << si % 64) != 0 {
            si += 1;
        }
        f = si as u64 * 2 + 3;
        if f > sqrt {
            f = n;
            continue;
        }
        let mut i = si;
        while i < sieve_len {
            sieve[i / 64] |= 1 << i % 64;
            i += f as usize;
        }
    }
    divisors
}

