		pub trait Bool { fn value() -> bool; }
		pub struct False {} impl Bool for False { fn value() -> bool { false } }
		pub struct True {} impl Bool for True { fn value() -> bool { true } }
		macro_rules! impl_primitive {
			($tr:ident; $($T:ty),+) => {
				pub trait $tr: Copy + Default + PartialEq + PartialOrd + Add<Output = Self> + Sub<Output = Self> + Mul<Output = Self> + Div<Output = Self> {}
				$(impl $tr for $T {})+
			};
		}
		impl_primitive![Number; i32, f64];
		impl_primitive![Float; f64];
	}

	#[derive(Default, Clone, Copy)]
	pub struct Complex<T>(pub T, pub T);

	impl<T: primitive::Number> Mul for Complex<T> {
		type Output = Self;
		fn mul(self, rhs: Self) -> Self {
			Complex(self.0 * rhs.0 - self.1 * rhs.1, self.0 * rhs.1 + self.1 * rhs.0)
		}
	}
	impl<T: Copy> MulAssign for Complex<T> where Complex<T>: Mul<Output = Complex<T>> {
		fn mul_assign(&mut self, rhs: Self) {
			*self = *self * rhs;
		}
	}
	macro_rules! impl_binops_complex {
		($(($op:ident, $method:ident)),+) => {$(
			impl<T: Copy + $op<Output = T>> $op for Complex<T> {
				type Output = Self;
				fn $method(self, rhs: Self) -> Self::Output {
					Complex((self.0).$method(rhs.0), (self.1).$method(rhs.1))
				}
			}
		)+};
	}

	macro_rules! impl_binops_complex_elem {
		(assign $(($op:ident, $method:ident)),+) => {$(
			impl<T: Copy + $op> $op<T> for Complex<T> {
				fn $method(&mut self, rhs: T) {
					(self.0).$method(rhs); (self.1).$method(rhs);
				}
			}
		)+};
	}

	macro_rules! impl_complex_float {
		($($Ts:ty),+; $F:ty) => {$(
			impl From<Complex<$Ts>> for Complex<$F> {
				fn from(src: Complex<$Ts>) -> Complex<$F> {
					Complex(src.0 as $F, src.1 as $F)
				}
			}
			impl_complex_float![$Ts => $F];
		)+};
		($($Ts:ty),+) => {$(
			impl_complex_float![$Ts => $Ts];
		)+};
		($T:ty => $F:ty) => {
			impl Complex<$T> {
				pub fn polar(rho: $F, theta: $F) -> Complex<$F> {
					Complex(rho * theta.cos(), rho * theta.sin())
				}
			}
		};
	}

	impl_binops_complex![(Add, add), (Sub, sub)];
	impl_binops_complex_elem![assign (DivAssign, div_assign)];
	impl_complex_float![f64];
