mod ft {
	use std;
	use super::number::primitive::*;
	use super::number::Complex;

	fn dft<Inverse: Bool>(mut a: Vec<Complex<f64>>) -> Vec<Complex<f64>>
	{
		let h = a.len().trailing_zeros();
		for i in 0..a.len() {
			let j = (0..h).map(|k| (i >> k) & 1).fold(0, |r, i| r << 1 | i);
			if i < j { a.swap(i, j); }
		}
		for b in (0..h).map(|i| 1 << i) {
			let w = if Inverse::value() {
				Complex::<f64>::polar(1., std::f64::consts::PI / (b as f64))
			} else {
				Complex::<f64>::polar(1., -std::f64::consts::PI / (b as f64))
			};
			let mut z = Complex(1., 0.);
			for j in 0..b {
				for i in (0..a.len() / (2 * b)).map(|i| i * 2 * b + j) {
					unsafe {
						let s = *a.get_unchecked(i);
						let t = *a.get_unchecked(i + b) * z;
						*a.get_unchecked_mut(i) = s + t;
						*a.get_unchecked_mut(i + b) = s - t;
					}
				}
				z *= w;
			}
		}
		if Inverse::value() {
			let n = a.len();
			for elem in a.iter_mut() {
				*elem /= n as f64;
			}
		}
		a
	}

	pub fn convolve<T>(a: &[T], b: &[T]) -> Vec<f64>
	where
		T: Number,
		Complex<T>: Into<Complex<f64>>
	{
		let deg = a.len() + b.len() - 1;
		let deg_ceil = (0..).map(|i| 1 << i).take_while(|&i| i < deg).fold(0, |_, i| i << 1);
		let a: Vec<Complex<f64>> = a.iter().map(|&a| Complex(a, T::default()).into()).chain((0..deg_ceil - a.len()).map(|_| Complex::<f64>::default())).collect();
		let b: Vec<Complex<f64>> = b.iter().map(|&b| Complex(b, T::default()).into()).chain((0..deg_ceil - b.len()).map(|_| Complex::<f64>::default())).collect();
		dft::<True>(dft::<False>(a).into_iter().zip(dft::<False>(b)).map(|(a, b)| a * b).collect()).into_iter().take(deg).map(|a| a.0).collect()
	}
}

