fn construct_graph(vertices: &Vec<(usize, usize)>, n: usize, distance: i64) -> Vec<Vec<usize>> {
    let num_v = vertices.len();
    assert_eq!(num_v, 4 * n * n);
    let mut graph = vec![vec![]; num_v];
    for from in 0..num_v {
        let (i, j) = vertices[from];
        let i = i as i64;
        let j = j as i64;
        let n = n as i64;

        for dx in 0..cmp::min(2 * n, distance + 1) {
            let dy2 = distance - dx * dx;
            if dy2 < 0 {
                continue;
            }
            let dy = (dy2 as f64).sqrt() as i64;
            if dy * dy + dx * dx != distance {
                continue;
            }

            for &(x, y) in vec![
                (i + dx, j + dy),
                (i + dx, j - dy),
                (i - dx, j + dy),
                (i - dx, j - dy),
            ]
            .iter()
            {
                if x >= 0 && y >= 0 && x < 2 * n && y < 2 * n {
                    let to = x * 2 * n + y;
                    graph[from].push(to as usize);
                }
            }
        }
    }
