fn solve(
    cur: usize,
    prev: usize,
    k: usize,
    h: &[i64],
    tbl: &mut Vec<Vec<Vec<Option<i64>>>>,
) -> i64 {
    if cur == h.len() {
        return 0;
    }

    if let Some(ret) = tbl[cur][prev][k] {
        return ret;
    }

    let mut ret = solve(cur + 1, cur + 1, k, h, tbl)
        + max(0, h[cur] - if prev == 0 { 0 } else { h[prev - 1] });

    if k >= 1 {
        ret = min(ret, solve(cur + 1, prev, k - 1, h, tbl));
    }

    tbl[cur][prev][k] = Some(ret);
    ret
}

