fn preprocess(adj: &Vec<Vec<(usize, usize, usize)>>) -> (Vec<Vec<usize>>, Vec<(usize, usize)>) {
    let n = adj.len();
    let mut parents = vec![vec![std::usize::MAX; (n as f64).log2() as usize + 1]; n];
    let mut dists = vec![(0, 0); n];
    let mut stack = vec![0];
    let mut used = vec![false; n];
    while stack.len() > 0 {
        let crt = stack.pop().unwrap();
        if used[crt] {
            continue;
        }
        used[crt] = true;
        for &(nxt, _, length) in adj[crt].iter() {
            if used[nxt] {
                continue;
            }
            parents[nxt][0] = crt;
            dists[nxt] = dists[crt];
            dists[nxt].0 += 1;
            dists[nxt].1 += length;
            stack.push(nxt);
        }
    }
    for i in 1..((n as f64).log2() as usize + 1) {
        for j in 0..n {
            if parents[j][i - 1] != std::usize::MAX {
                parents[j][i] = parents[parents[j][i - 1]][i - 1];
            }
        } 
    }
    (parents, dists)
}

fn find_lca(u: usize, v: usize, parents: &[Vec<usize>], dists: &[(usize, usize)]) -> usize {
    let (mut u, mut v) = (u, v);
    if dists[u].0 < dists[v].0 {
        swap(&mut u, &mut v);
    }
    while dists[u].0 > dists[v].0 {
        let diff = ((dists[u].0 - dists[v].0) as f64).log2() as usize;
        u = parents[u][diff];
    }
    if u == v {
        return u;
    }
    while u != v {
        let mut depth = (dists[u].0 as f64).log2() as usize;
        while parents[u][depth] == parents[v][depth] && depth > 0 {
            depth -= 1;
        }
        u = parents[u][depth];
        v = parents[v][depth];
    }
    u
}

fn dfs(qset: &HashMap<usize, Vec<usize>>, adj: &[Vec<(usize, usize, usize)>]) -> HashMap<(usize, usize), (usize, usize)> {
    let mut qmap = HashMap::new();
    let mut stack = vec![(0, std::usize::MAX, std::usize::MAX)];
    let mut state = vec![(0, 0); adj.len() - 1];
    let mut used = vec![false; adj.len()];
    while stack.len() > 0 {
        let &(crt, prv, index) = stack.last().unwrap();
        if used[crt] {
            if prv < adj.len() {
                state[adj[prv][index].1].0 -= 1;
                state[adj[prv][index].1].1 -= adj[prv][index].2;
            }
            stack.pop().unwrap();
            continue;
        }
        used[crt] = true;
        if prv < adj.len() {
            state[adj[prv][index].1].0 += 1;
            state[adj[prv][index].1].1 += adj[prv][index].2;
        }
        if qset.contains_key(&crt) {
            for &col in qset.get(&crt).unwrap() {
                qmap.insert((crt, col), state[col]);
            }
        }
        for i in 0..adj[crt].len() {
            if adj[crt][i].0 == prv {
                continue;
            }
            stack.push((adj[crt][i].0, crt, i));
        }
    }
    qmap
}

