// 2. 根の色が白で全ての頂点を黒にして根に戻る最小値
// 3. 根の色が黒で全ての頂点を黒にして根に戻る最小値
// 4. 根の色が白で全ての頂点を黒にして根は白で根に戻る最小値
// 5. 根の色が黒で全ての頂点を黒にして根は白で根に戻る最小値

fn run() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let e: Vec<(usize, usize)> = (1..n).map(|_| {
        let x: usize = it.next().unwrap().parse().unwrap();
        let y: usize = it.next().unwrap().parse().unwrap();
        (x - 1, y - 1)
    }).collect();
    let s: Vec<char> = it.next().unwrap().chars().collect();
    type Value = (u32, u32, u32, u32, u32, u32);
    type Edge = usize;
    let init = |_v: usize| -> Value {
        (1, 0, 1, 0, 0, 1)
    };
    let inf = 1_000_000;
    let merge = |a: &Value, b: &Value, c: &Edge| -> Value {
        if s[*c] == 'B' && b.1 == 0 {
            return *a;
        }
        let mut res = (inf, inf, inf, inf, inf, inf);
        if s[*c] == 'B' {
            res.0 = min(a.2 + 1 + b.0, 1 + b.2 + 1 + a.1);
            res.1 = min(a.3 + 1 + b.0, 1 + b.2 + 1 + a.0);
            res.2 = min(a.4 + 1 + b.2 + 1, 1 + b.2 + 1 + a.3);
            res.3 = min(a.5 + 1 + b.2 + 1, 1 + b.2 + 1 + a.2);
            res.4 = min(a.2 + 1 + b.2 + 1, 1 + b.2 + 1 + a.5);
            res.5 = min(a.3 + 1 + b.2 + 1, 1 + b.2 + 1 + a.4);
        } else {
            res.0 = min(a.2 + 1 + b.1, 1 + b.3 + 1 + a.1);
            res.1 = min(a.3 + 1 + b.1, 1 + b.3 + 1 + a.0);
            res.2 = min(a.4 + 1 + b.3 + 1, 1 + b.3 + 1 + a.3);
            res.3 = min(a.5 + 1 + b.3 + 1, 1 + b.3 + 1 + a.2);
            res.4 = min(a.2 + 1 + b.3 + 1, 1 + b.3 + 1 + a.5);
            res.5 = min(a.3 + 1 + b.3 + 1, 1 + b.3 + 1 + a.4);
        }
        res.0 = min(res.0, res.2);
        res.1 = min(res.1, res.3);
        res
    };
    let mut solver = Rerooting::new(n, init, merge);
    for (x, y) in e {
        solver.add_edge_bi(x, y, y, x);
    }
    let dp = solver.solve();
    let mut ans = inf;
    for i in 0..n {
        if s[i] == 'B' {
            ans = min(ans, dp[i].1);
        } else {
            ans = min(ans, dp[i].0);
        }
    }
    println!("{}", ans);
}

fn main() {
    run();
}

