    match c {
        'R' => 1,
        'G' => 2,
        'B' => 3,
        _ => unreachable!("invalid color")
    }
}

const MOD: i64 = 998244353;

fn main() {
    input! {
        n: usize,
        s: chars
    };

    let s = s.into_iter().map(|c| tou(c)).collect::<Vec<_>>();

    let three = vec![
        vec![],
        vec![11, 14],
        vec![7, 13],
        vec![6, 9],
    ];
    let two = vec![
        vec![],
        vec![8, 12],
        vec![4, 12],
        vec![4, 8]
    ];

    let mut ways = 1;
    let mut ord = vec![0; 16];
    ord[0] = n as i64;
    for i in 0..3*n {
        // find 3rd color
        let mut sum = 0;
        let mut idx = 0;
        for &l in &three[s[i]] {
            sum += ord[l];
            if ord[l] >= 1 {
                idx = l;
            }
        }
        if sum >= 1 {
            ways *= sum;
            ways %= MOD;
            ord[idx] -= 1;
            // debug!(3, ways, ord);
            continue;
        }
        // otherwise, find 2nd color
        for &l in &two[s[i]] {
            sum += ord[l];
            if ord[l] >= 1 {
                idx = l;
            }
        }
        if sum >= 1 {
            ways *= sum;
            ways %= MOD;
            ord[idx] -= 1;
            ord[idx+s[i]] += 1;
            // debug!(2, ways, ord);
            continue;
        }
        ways *= ord[0];
        ways %= MOD;
        ord[0] -= 1;
        ord[4*s[i]] += 1;
        // debug!(1, ways, ord);
    }
    println!("{}", ways);
}

