fn run() {
    input! {
        n: usize,
        s: u64,
        p: [(u64, u64); n],
    }
    if p[0].0 > s {
        let ans = p[n - 1].0 - s;
        println!("{}", ans);
        return;
    }
    if p[n - 1].0 < s {
        let ans = s - p[0].0;
        println!("{}", ans);
        return;
    }
    let k = p.iter().position(|p| p.0 > s).unwrap();
    let mut x = p;
    let mut y = x.split_off(k);
    x.reverse();
    let mut ans = y.last().unwrap().0 - x.last().unwrap().0;
    let mut pos = if x.last().unwrap().1 >= y.last().unwrap().1 {
        x.last_mut().unwrap().1 += y.pop().unwrap().1;
        true
    } else {
        y.last_mut().unwrap().1 += x.pop().unwrap().1;
        false
    };
    while x.len() > 0 && y.len() > 0 {
        let &(a, b) = x.last().unwrap();
        let &(c, d) = y.last().unwrap();
        if b >= d {
            x.last_mut().unwrap().1 += y.pop().unwrap().1;
            if !pos {
                ans += c - a;
                pos ^= true;
            }
        } else {
            y.last_mut().unwrap().1 += x.pop().unwrap().1;
            if pos {
                ans += c - a;
                pos ^= true;
            }
        }
    }
    if let Some((x, _)) = x.pop() {
        ans += s - x;
    }
    if let Some((y, _)) = y.pop() {
        ans += y - s;
    }
    println!("{}", ans);
}

