    let mut left = VecDeque::new();
    let mut right = VecDeque::new();
    for i in 0..n {
        let (x, p): (usize, usize) = readln();
        if x < s {
            left.push_back((x, p));
        } else {
            right.push_front((x, p));
        }
    }

    let mut used: usize = 0;
    let mut result = Vec::new();
    let mut last = 'l';
    for _ in 0..n {
        if left.is_empty() {
            let (x, p) = right.pop_front().unwrap();
            result.push((x, p));
        } else if right.is_empty() {
            let (x, p) = left.pop_front().unwrap();
            result.push((x, p));
        } else {
            let &(lx, lp) = left.front().unwrap();
            let &(rx, rp) = right.front().unwrap();
            let right_power = if last == 'l' { rp + used } else { rp };
            let left_power = if last == 'r' { lp + used } else { lp };
            if right_power <= left_power {
                // choose right
                right.pop_front();
                result.push((rx, rp));
                used += rp;
                last = 'r';
            } else {
                left.pop_front();
                result.push((lx, lp));
                used += lp;
                last = 'l';
            }
        }
    }
    result.reverse();
    let mut cur = s;
    let mut answer: usize = 0;
    for (x, p) in result {
        answer += (cur as i64 - x as i64).abs() as usize;
        cur = x;
    }
