use std::io;
use std::str::FromStr;
use std::cmp;
use std::cmp::Ordering;
use std::collections::BinaryHeap;
use std::collections::HashMap;
use std::io::{stdout, Write, BufWriter};

const INT_MAX: i64 = 200001;

struct SegmentTree {
    n: usize, 
    dat: Vec<i64>
}

impl SegmentTree {
    fn new(nn: usize) -> SegmentTree {
        let mut n = 1;
        while n < nn {
            n *= 2;
        }
        let dat = vec![INT_MAX; 2*n-1];
        return SegmentTree {n: n, dat: dat};
    }

    fn update(&mut self, k: usize, a: i64) {
        let mut i = k + (self.n - 1);
        self.dat[i] = a;
        while i > 0 {
            i = (i - 1) / 2;
            self.dat[i] = cmp::min(self.dat[i*2+1], self.dat[i*2+2]);
        }
    }
    fn query(&self, a: usize, b: usize, k: usize, l: usize, r: usize) -> i64 {
        if (r <= a) || (b <= l) {
            return INT_MAX;
        }
        if (a <= l) && (r <= b) {
            return self.dat[k];
        }
        let vl = self.query(a, b, k*2+1, l, (l+r)/2);
        let vr = self.query(a, b, k*2+2, (l+r)/2, r);
        return cmp::min(vl, vr);
    }
}

enum EvenOdd {
    E,
    O,
}

#[derive(Copy, Clone, Eq, PartialEq)]
struct Item {
    v: i64,
    i: usize,
    left: usize,
    right: usize,
}

// Priority Queue
impl Ord for Item {
    fn cmp(&self, other: &Item) -> Ordering {
        other.v.cmp(&self.v)
    }
}

impl PartialOrd for Item {
    fn partial_cmp(&self, other: &Item) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn join(v: Vec<i64>) -> String {
    let mut ret = String::new();
    let n = v.len();
    for (i, x) in v.iter().enumerate() {
        if i == n - 1 {
            ret.push_str(&format!("{}", x));
        } else {
            ret.push_str(&format!("{} ", x));
        }
    }
    return ret
}

fn gets() -> String {
    let mut buf = String::new();
    io::stdin().read_line(&mut buf).ok();
    return buf
}

fn split<T>(buf: String) -> Vec<T> 
  where T: std::str::FromStr,
  <T as std::str::FromStr>::Err: std::fmt::Debug {
    buf.split_whitespace()
        .map(|n| n.parse::<T>().unwrap())
        .collect()
}

fn main() {
    let n = usize::from_str(gets().trim()).unwrap();
    let arr: Vec<i64> = split(gets());

    let mut st_even = SegmentTree::new(n);
    let mut st_odd = SegmentTree::new(n);
    let mut h = HashMap::new();

    for (i, a) in arr.iter().enumerate() {
        h.insert(a, i);
        match i%2 {
            0 => st_even.update(i, a.clone()),
            _ => st_odd.update(i, a.clone()),
        }
    }

    let wrap_query = |t: EvenOdd, a: usize, b: usize, k: usize, l: usize| {
        match (t, a%2) {
            (EvenOdd::E, 0) => st_even.query(a, b, k, l, st_even.n),
            (EvenOdd::E, 1) => st_odd.query(a, b, k, l, st_odd.n),
            (EvenOdd::O, 0) => st_odd.query(a, b, k, l, st_odd.n),
            _ => st_even.query(a, b, k, l, st_even.n),
        }
    };

    let mut q = vec![0; n];
    let mut pq = BinaryHeap::<Item>::new();
    let x = wrap_query(EvenOdd::E, 0, n, 0, 0);
    pq.push(Item{v: x, i: h[&x], left: 0, right: n});
    let mut ii = 0;
    while pq.len() != 0 {
        let item = pq.pop().unwrap();
        q[ii] = item.v;
        ii = ii + 1;
        let q1 = wrap_query(EvenOdd::O, item.i, item.right, 0, 0);
        let j = h[&q1];
        q[ii] = q1;
        ii = ii + 1;

        if item.i - item.left > 1 {
            let x = wrap_query(EvenOdd::E, item.left, item.i, 0, 0);
            pq.push(Item{v: x, i: h[&x], left: item.left, right: item.i});
        }
        if j - (item.i + 1) > 1 {
            let x = wrap_query(EvenOdd::E, item.i+1, j, 0, 0);
            pq.push(Item{v: x, i: h[&x], left: item.i + 1, right: j});
        }
        if item.right - (j + 1) > 1 {
            let x = wrap_query(EvenOdd::E, j+1, item.right, 0, 0);
            pq.push(Item{v: x, i: h[&x], left: j + 1, right: item.right});
        }
    }
    let out = stdout();
    let mut out = BufWriter::new(out.lock());
    writeln!(out, "{}", join(q)).unwrap();
}

use io::*;
use std::collections::BinaryHeap;
use std::cmp::Ordering;

#[derive(Eq)]

struct Node {
    v1: usize,
    v2: usize,
    child: Vec<(usize,usize)>
}

impl Ord for Node {
    fn cmp(&self, other: &Node) -> Ordering {
        other.v1.cmp(&self.v1)
    }
}

impl PartialOrd for Node {
    fn partial_cmp(&self, other: &Node) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl PartialEq for Node {
    fn eq(&self, other: &Node) -> bool {
        self.v1 == other.v1
    }
}

struct SegTree {
    t: Vec<(usize,usize)>,
    len: usize
}

impl SegTree {
    fn new(v: &Vec<usize>) -> SegTree {
        let mut l = 1;
        while l < v.len() {
            l *= 2;
        }
        let mut t: Vec<(usize,usize)> = vec![(usize::max_value(),usize::max_value()); 2 * l - 1];
        for i in 0..v.len() {
            t[i + l - 1] = (i,v[i]);
        }
        for i in 1..l {
            let idx = l - i - 1;
            t[idx] = if t[2*idx+1].1 <= t[2*idx+2].1 {
                t[2*idx+1]
            } else {
                t[2*idx+2]
            }
        }
        SegTree{t: t, len: l}
    }

    fn range(&self, mut l: usize, mut r: usize) -> (usize,usize) {
        l += self.len - 1;
        r += self.len - 1;
        let mut ret = (0,usize::max_value());
        while l < r {
            if l % 2 == 0 && ret.1 > self.t[l].1 {
                ret = self.t[l];
            }
            l /= 2;
            if r % 2 == 0 && ret.1 > self.t[r - 1].1 {
                ret = self.t[r - 1];
            }
            r = (r - 1) / 2;
        }
        ret
    }
}

fn main() {
    let input = read_string();
    let mut sc = Scanner::new(&input);
    let n: usize = sc.next();
    let ps: Vec<usize> = sc.next_vec(n);
    let (ev,ov) = partition(&ps);
    let et: SegTree = SegTree::new(&ev);
    let ot: SegTree = SegTree::new(&ov);
    let mut pq: BinaryHeap<Node> = BinaryHeap::new();
    let head = solve(&et, &ot ,0, n);
    print!("{} {}", head.v1, head.v2);
    for (l,r) in head.child {
        pq.push(solve(&et, &ot, l, r));
    }
    loop {
        if pq.is_empty() {
            break;
        }
        let node = pq.pop().unwrap();
        print!(" {} {}", node.v1, node.v2);
        for (l,r) in node.child {
            pq.push(solve(&et, &ot, l, r));
        }
    }
    print!("\n");
}

fn partition(v: &Vec<usize>) -> (Vec<usize>,Vec<usize>) {
    let mut ev: Vec<usize> = vec![0; (v.len() + 1) / 2];
    let mut ov: Vec<usize> = vec![0; v.len() / 2];
    for i in 0..v.len() {
        if i % 2 == 0 {
            ev[i / 2] = v[i];
        } else {
            ov[i / 2] = v[i];
        }
    }
    (ev,ov)
}

fn solve(et: &SegTree, ot: &SegTree, l: usize, r: usize) -> Node {
    let (ei, e): (usize,usize);
    let (oi, o): (usize,usize);
    if l % 2 == 0 {
        let en = et.range((l + 1) / 2, (r + 1) / 2);
        ei = en.0 * 2;
        let on = ot.range(ei / 2, r / 2);
        oi = on.0 * 2 + 1;
        e = en.1;
        o = on.1;
    } else {
        let en = ot.range(l / 2, r / 2);
        ei = en.0 * 2 + 1;
        let on = et.range((ei + 1) / 2, (r + 1) / 2);
        oi = on.0 * 2;
        e = en.1;
        o = on.1;
    }
    let mut child: Vec<(usize,usize)> = Vec::new();
    if l < ei {
        child.push((l, ei));
    }
    if ei + 1 < oi {
        child.push((ei + 1, oi));
    }
    if oi + 1 < r {
        child.push((oi + 1, r));
    }
    Node{v1: e, v2: o, child: child}
}

