macro_rules! input {
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, [ $t:tt ]) => {{
        let len = read_value!($next, usize);
        (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    }};

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

/**
 * Segment Tree. This data structure is useful for fast folding on intervals of an array
 * whose elements are elements of monoid I. Note that constructing this tree requires the identity
 * element of I and the operation of I.
 * Verified by: yukicoder No. 259 (http://yukicoder.me/submissions/100581)
 *              AGC015-E (http://agc015.contest.atcoder.jp/submissions/1461001)
 */
struct SegTree<I, BiOp> {
    n: usize,
    dat: Vec<I>,
    op: BiOp,
    e: I,
}

impl<I, BiOp> SegTree<I, BiOp>
    where BiOp: Fn(I, I) -> I,
          I: Copy {
    pub fn new(n_: usize, op: BiOp, e: I) -> Self {
        let mut n = 1;
        while n < n_ { n *= 2; } // n is a power of 2
        SegTree {n: n, dat: vec![e; 2 * n - 1], op: op, e: e}
    }
    /* ary[k] <- v */
    pub fn update(&mut self, idx: usize, v: I) {
        let mut k = idx + self.n - 1;
        self.dat[k] = v;
        while k > 0 {
            k = (k - 1) / 2;
            self.dat[k] = (self.op)(self.dat[2 * k + 1], self.dat[2 * k + 2]);
        }
    }
    /* [a, b) (note: half-inclusive)
     * http://proc-cpuinfo.fixstars.com/2017/07/optimize-segment-tree/ */
    pub fn query(&self, mut a: usize, mut b: usize) -> I {
        let mut left = self.e;
        let mut right = self.e;
        a += self.n - 1;
        b += self.n - 1;
        while a < b {
            if (a & 1) == 0 {
                left = (self.op)(left, self.dat[a]);
            }
            if (b & 1) == 0 {
                right = (self.op)(self.dat[b - 1], right);
            }
            a = a / 2;
            b = (b - 1) / 2;
        }
        (self.op)(left, right)
    }
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        p: [i32; n],
    }
    const INF: usize = 1 << 20;
    let mut even: SegTree<(i32, usize), _> = SegTree::new(n / 2, max, (-(INF as i32), INF));
    let mut odd = SegTree::new(n / 2, max, (-(INF as i32), INF));
    for i in 0 .. n / 2 {
        even.update(i, (-p[2 * i], 2 * i));
        odd.update(i, (-p[2 * i + 1], 2 * i + 1));
    }
    let mut que = BinaryHeap::new();
    que.push((even.query(0, n / 2), 0, n));
    let mut ans = Vec::new();
    while let Some(((opt, idx1), l, r)) = que.pop() {
        let (paired, idx2) =
            if idx1 % 2 == 0 {
                odd.query(idx1 / 2, r / 2)
            } else {
                even.query(idx1 / 2 + 1, (r + 1) / 2)
            };
        ans.push(-opt);
        ans.push(-paired);
        if l % 2 == 0 {
            if idx1 > l {
                que.push((even.query(l / 2, idx1 / 2), l, idx1));
            }
            if idx1 + 1 < idx2 {
                que.push((odd.query(idx1 / 2, idx2 / 2), idx1 + 1, idx2));
            }
            if idx2 + 1 < r {
                que.push((even.query(idx2 / 2 + 1, r / 2), idx2 + 1, r));
            }
        } else {
            if idx1 > l {
                que.push((odd.query(l / 2, idx1 / 2), l, idx1));
            }
            if idx1 + 1 < idx2 {
                que.push((even.query(idx1 / 2 + 1, idx2 / 2), idx1 + 1, idx2));
            }
            if idx2 + 1 < r {
                que.push((odd.query(idx2 / 2, r / 2), idx2 + 1, r));
            }
        }
    }
    for i in 0 .. n {
        puts!("{}{}", ans[i], if i == n - 1 { "\n" } else { " " });
    }
}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

