fn solve(n: i64, k: i64) -> Option<Vec<(i64, i64, i64)>> {
    let mut ans = vec![];
    let le = (k+1)/2;
    for i in 0..n {
        if k+2*n+i*2 > 3*n-1+k {
            break;
        }
        if 2*n+i >= 2*n+k {
            break;
        }
        ans.push((k+i, 2*n+i, k+2*n+i*2));
    }
    // debug!(ans);
    let le = ans.len();
    let ni = n as usize;
    let mut used = vec![0; 3*ni];
    for i in 0..le {
        let num = ans[i].0 - k;
        if num < 0 || num >= 2*n {
            return None;
        }
        used[num as usize] += 1;
        let num = ans[i].1 - k;
        if num < 0 || num >= 2*n {
            return None;
        }
        used[num as usize] += 1;
        used[2*ni+i*2] = 1;
    }

    let mut left = vec![];
    for i in 0..2*ni {
        if used[i] >= 2 {
            return None;
        }
        if used[i] == 0 {
            left.push(i);
        }
    }
    let mut right = vec![];
    for i in 2*ni..3*ni {
        if used[i] == 0 {
            right.push(i);
        }
    }
    let ln = left.len();
    for w in 0..ln/2 {
        let a = left[w] as i64;
        let b = left[w+ln/2] as i64;
        let c = right[w] as i64;
        ans.push((a+k, b+k, c+k));
    }
    let n = ans.len();
    for i in 0..n {
        if ans[i].0 + ans[i].1 > ans[i].2 {
            return None;
        }
    }
    return Some(ans);
}

fn main() {
    input! {
        n: i64, k: i64
    };
    if let Some(a) = solve(n, k) {
        for i in 0..(n as usize) {
            println!("{} {} {}", a[i].0, a[i].1, a[i].2);
        }
    } else {
        println!("-1");
    }
}

