    input! {
        s: String,
        m: usize,
        p: [(usize1, usize); m],
    }
    let a: Vec<u32> = s.chars().map(|c| c as u32 - 'a' as u32).collect();
    let n = a.len();
    let mut u = union_find::UF::new(n + 1);
    for (l, r) in p {
        u.unite(l, r);
    }
    for i in 0..n {
        u.unite(i, n - i);
    }
    let mut dp = vec![0; n + 1];
    dp[u.root(0)] += a[0];
    for i in 1..n {
        dp[u.root(i)] += (a[i] - a[i - 1] + 26) % 26;
    }
    dp[u.root(n)] += 26 - a[n - 1];
    for i in 0..(n + 1) {
        if dp[i] % 26 != 0 {
            println!("NO");
            return;
        }
    }
    println!("YES");
}

