fn primes(n: usize) -> Vec<usize> {
    if n < 2 {
        return vec![];
    }
    let mut tab = vec![true; n + 1];
    let mut ps = vec![2];
    for i in 2..n / 2 + 1 {
        tab[i * 2] = false;
    }
    let mut p = 3;
    while p * p <= n {
        if tab[p] {
            ps.push(p);
            for i in 2..n / p + 1 {
                tab[i * p] = false;
            }
        }
        p += 2;
    }
    while p <= n {
