fn get_primes(n: usize) -> Vec<usize> {
    let mut is_prime = vec![true; n + 1];
    is_prime[0] = false;
    is_prime[1] = false;

    for p in 2..(n + 1) {
        if is_prime[p] {
            let mut c = 2;
            while c * p <= n {
                is_prime[c * p] = false;
                c += 1;
            }
        }
    }

    let mut primes = Vec::new();
    for i in 2..(n + 1) {
        if is_prime[i] {
            primes.push(i);
        }
    }
    primes
