    let mut from = rects[0].0;
    let mut to = rects[0].0;
    let mut bottom = 0;

    let mut left = SlopeSet::new();
    left.push_left(-INF);
    left.push_left(from);

    let mut right = SlopeSet::new();
    right.push_right(INF);
    right.push_right(from);


    for i in 1..n {
        let fl = rects[i-1].0;
        let fr = rects[i-1].1;
        let tl = rects[i].0;
        let tr = rects[i].1;
        from -= tr-tl;
        left.add(-tr+tl);
        to += fr-fl;
        right.add(fr-fl);

        let (l0, l1) = left.peek_left_pair();
        let (r0, r1) = right.peek_right_pair();

        // println!("{}={}({} {}){}={}", l0, l1, from, to, r0, r1);
        // println!("{}", bottom);

        let position = tl;
        if position <= l1 {
