struct Negative;
impl TE for Negative {
    type T = (i64, i64);
    type E = i64;
    fn fold(l: Self::T, r: Self::T) -> Self::T {
        if l.0 + l.1 <= r.0 + r.1 {
            l
        } else {
            r
        }
    }
    fn eval(x: Self::T, f: Self::E) -> Self::T {
        (x.0 + f, x.1)
    }
    fn merge(g: Self::E, h: Self::E) -> Self::E {
        g + h
    }
    fn e() -> Self::T {
        (std::i64::MAX / 3, std::i64::MAX / 3)
    }
    fn id() -> Self::E {
        0
    }
}

struct Positive;
impl TE for Positive {
    type T = (i64, i64);
    type E = i64;
    fn fold(l: Self::T, r: Self::T) -> Self::T {
        if l.0 + r.1 <= r.0 + l.1 {
            l
        } else {
            r
        }
    }
    fn eval(x: Self::T, f: Self::E) -> Self::T {
        (x.0 + f, x.1)
    }
    fn merge(g: Self::E, h: Self::E) -> Self::E {
        g + h
    }
    fn e() -> Self::T {
        (std::i64::MAX / 3, 0)
    }
    fn id() -> Self::E {
        0
    }
}

fn run() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let q: usize = it.next().unwrap().parse().unwrap();
    let a: usize = it.next().unwrap().parse().unwrap();
    let b: usize = it.next().unwrap().parse().unwrap();
    let mut z: Vec<(i64, i64)> = (0..n).map(|k| (std::i64::MAX / 3, k as i64)).collect();
    z[a - 1].0 = 0;
    let mut pos = LazySegmentTree::<Positive>::build_by(&z);
    let mut neg = LazySegmentTree::<Negative>::build_by(&z);
    let mut now = b - 1;
    for _ in 0..q {
        let x: usize = it.next().unwrap().parse().unwrap();
        let x = x - 1;
        let d = (max(x, now) - min(x, now)) as i64;
        let l = pos.find(0, x + 1);
        let r = neg.find(x, n);
        neg.update(0, n, d);
        pos.update(0, n, d);
        let v = neg.find(now, now + 1);
        let u = min(l.0 + x as i64 - l.1, r.0 + r.1 - x as i64);
        if u < v.0 {
            neg.update(now, now + 1, u - v.0);
            pos.update(now, now + 1, u - v.0);
        }
        now = x;
    }
    let mut ans = std::i64::MAX;
    for i in 0..n {
        let v = pos.find(i, i + 1);
        ans = min(ans, v.0);
    }
    println!("{}", ans);
}

