#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn calc(
    depth: usize,
    v: usize,
    seq: &Vec<usize>,
    costs: &Vec<i64>,
    memo: &mut Vec<Vec<i64>>,
) -> i64 {
    let n = seq.len();
    if depth == n {
        return 0;
    }
    if memo[depth][v] != -1 {
        return memo[depth][v];
    }
    let mut ret = 1 << 60;
    if seq[depth] < v {
        // left move
        ret = std::cmp::min(ret, calc(depth + 1, v, seq, costs, memo) + costs[0]);
    } else {
        // right move
        ret = std::cmp::min(ret, calc(depth + 1, v, seq, costs, memo) + costs[1]);
        // nop
        ret = std::cmp::min(ret, calc(depth + 1, seq[depth], seq, costs, memo));
    };
    // println!("{} {} {}", depth, v, ret);
    memo[depth][v] = ret;
    return ret;
}

fn main() {
    let n = read::<usize>();
    let mut costs = vec![0, 0];
    costs[1] = read::<i64>();
    costs[0] = read::<i64>();
    let mut seq = vec![0; n];
    for i in 0..n {
        seq[i] = read::<usize>() - 1;
    }
    let mut memo = vec![vec![-1; n]; n];
    let ans = calc(0, 0, &seq, &costs, &mut memo);
    println!("{}", ans);
}

