    dp[0][n] = 0;

    for i in 0..n {
        let mut upper = 0;
        let mut lower = 0;
        for j in 0..i {
            if p[i] < p[j] {
                upper += 1;
            } else {
                lower += 1;
            }
        }

        let fr = i % 2;
        let to = 1 - fr;
        for j in 0..n + 1 {
            dp[to][j] = INF;
        }

        for j in 0..n + 1 {
            if dp[fr][j] == INF {
                continue;
            }
            let base = dp[fr][j];
            if j == n {
                dp[to][i] = min(dp[to][i], base + upper * a + lower * b);
            } else {
                if p[j] < p[i] {
                    dp[to][i] = min(dp[to][i], base);
                }
            }
            if j == n {
                dp[to][j] = min(dp[to][j], base);
            } else {
                if p[i] > p[j] {
                    dp[to][j] = min(dp[to][j], base + a);
                } else {
                    dp[to][j] = min(dp[to][j], base + b);
                }
            }
        }
    }
    let mut ans = INF;
    for i in 0..n {
        ans = min(ans, dp[n % 2][i]);
    }
    println!("{}", ans);
}

