    let mut center = None;
    let mut suffix = vec![];
    for i in 0..n {
        if pos[i] < count[s[i]] / 2 {
            prefix.push(i);
        } else if count[s[i]] % 2 == 1 && pos[i] * 2 + 1 == count[s[i]] {
            center = Some(i);
        } else {
            suffix.push(i);
        }
    }

    assert_eq!(prefix.len(), suffix.len());
    let mut initial_cost = 0;
    for (to, from) in prefix.iter().cloned().enumerate() {
        initial_cost += from - to;
    }
    if let Some(c) = center {
        initial_cost += suffix.iter().filter(|&&s| s < c).count();
