// ---------- begin Strongly Connected Components ----------
struct SCCforSAT2 {
    graph: Vec<Vec<usize>>,
    inv_graph: Vec<Vec<usize>>,
    id: Vec<usize>,
}

impl SCCforSAT2 {
    pub fn new(size: usize) -> Self {
        SCCforSAT2 {
            graph: vec![vec![]; size],
            inv_graph: vec![vec![]; size],
            id: Vec::with_capacity(size),
        }
    }
    pub fn clear(&mut self) {
        for (x, y) in self.graph.iter_mut().zip(self.inv_graph.iter_mut()) {
            x.clear();
            y.clear();
        }
        self.id.clear();
    }
    pub fn add_edge(&mut self, from: usize, to: usize) {
        self.graph[from].push(to);
        self.inv_graph[to].push(from);
    }
    pub fn build(&mut self) {
        let size = self.graph.len();
        let mut visited = vec![false; size];
        let mut q = vec![];
        let mut stack = vec![];
        for v in 0..size {
            if visited[v] {
                continue;
            }
            stack.clear();
            stack.push((v, 0));
            while let Some((v, s)) = stack.pop() {
                visited[v] = true;
                let mut finish = true;
                for (i, &u) in self.graph[v][s..].iter().enumerate() {
                    if !visited[u] {
                        finish = false;
                        stack.push((v, s + i + 1));
                        stack.push((u, 0));
                        break;
                    }
                }
                if finish {
                    q.push(v);
                }
            }
        }
        self.id.clear();
        self.id.resize(size, size);
        let mut counter = 0;
        let mut stack = vec![];
        for &v in q.iter().rev() {
            if self.id[v] < size {
                continue;
            }
            self.id[v] = counter;
            stack.clear();
            stack.push(v);
            while let Some(v) = stack.pop() {
                self.id[v] = counter;
                for &u in self.inv_graph[v].iter() {
                    if self.id[u] == size {
                        self.id[u] = counter;
                        stack.push(u);
                    }
                }
            }
            counter += 1;
        }
    }
    pub fn get_array(&self) -> Vec<usize> {
        self.id.clone()
    }
}
// ---------- end Strongly Connected Components ----------
