            let (_, l, r) = spans[spans_pointer];
            seg.add(l, r + 1, 1, 0, 0, m + 1);
            spans_pointer += 1;
        }
        answers[mi] = spans.len() - spans_pointer;
        let mut cur_pos = mi;
        while cur_pos <= m {
            answers[mi] += seg.getsum(cur_pos, cur_pos + 1, 0, 0, m + 1) as usize;
            cur_pos += mi;
        }
    }
