const INF: i64 = 1000000000000000;
const MOD: i64 = 1000000007;

fn mul(x: i64, y: i64) -> i64 {
    (x * y) % MOD
}

fn sub(x: i64, y: i64) -> i64 {
    (x + MOD - y) % MOD
}

fn sq(x: i64) -> i64 {
    mul(x, x)
}

fn main() {
    let (N, M) = reads!(usize, usize);
    let mut edges = vec![vec![]; N];

    let (mut S, mut T) = reads!(usize, usize);
    S -= 1; T -= 1;

    for _ in 0..M {
        let (mut U, mut V, D) = reads!(usize, usize, i64);
        U -= 1; V -= 1;
        edges[U].push((V, D));
        edges[V].push((U, D));
    }

    fn dijkstra(s: usize, edges: &Vec<Vec<(usize, i64)>>) -> Vec<i64> {
        let mut dist = vec![INF; edges.len()];
        dist[s] = 0;
        let mut heap = BinaryHeap::new();
        heap.push((0, s));

        while !heap.is_empty() {
            let (d, x) = heap.pop().unwrap();
            if dist[x] < -d {
                continue;
            }
            for &(y, c) in &edges[x] {
                if dist[x] + c < dist[y] {
                    dist[y] = dist[x] + c;
                    heap.push((-dist[y], y));
                }
            }
        }
        dist
    }

    let dS = dijkstra(S, &edges);
    let dT = dijkstra(T, &edges);

    fn count(s: usize, edges: &Vec<Vec<(usize, i64)>>, dist: &Vec<i64>) -> Vec<i64> {
        let N = edges.len();
        let mut ns = vec![0; N]; ns[s] = 1;

        let mut vs = (0..N).collect::<Vec<usize>>();
        vs.sort_by_key(|&i| dist[i]);

        for &x in &vs {
            for &(y, d) in &edges[x] {
                if dist[y] - dist[x] == d {
                    ns[y] = (ns[y] + ns[x]) % 1000000007;
                }
            }
        }

        ns
    }

    let nS = count(S, &edges, &dS);
    let nT = count(T, &edges, &dT);

