    // assert!(nS[T] == nT[S]);

    let mut result = sq(nS[T]);

    for i in 0..N {
        if dS[i] == dT[i] && dS[i] + dT[i] == dS[T] {
            result = sub(result, sq(mul(nS[i], nT[i])));
        }
