            }
        }
        let (ret, _) = self.peaces[0];
        Some(Point{x: ret.x + left, y: ret.y + top})
    }
    fn rotate_right(&self) -> Piece {
        let mut vec = vec![vec![-1; self.height]; self.width];
        for &(p, n) in &self.peaces {
            vec[p.x][self.height - p.y - 1] = n;
        }
        Piece::read(&vec)
    }
