fn solve() {
	let n = read!(usize);
	let a_tmp = read!([usize]);
	let mut a: Vec<usize> = a_tmp.iter().map(|x| x-1).collect();
	let mut res = vec![0;n];
	for i in 0..n {
		res[a[i]] += 1;
	}

	let mut ans = vec![];
	let mut set = BTreeSet::new();
	for i in 0..n {
		set.insert(i);
	}
	let mut prev = n;
	let mut val = n;
	loop {
		set.remove(&val);
		if set.len()<=4 {break;}
		let mut it = set.iter();
		val = it.next().unwrap().clone();
		if val==prev {
			val = it.next().unwrap().clone();
		}
		let k = set.len();
		let y = a[val];
		if set.contains(&y) && k-1==res[y] {val=y;}
		ans.push(val);
		res[a[val]] -= 1;
		prev = a[val];
	}
	let mut v = vec![];
	for &i in set.iter(){
		v.push(i);
	}

	let mut ret = vec![];
	let mut p = vec![];
	let mut seen = vec![false;v.len()];
	search(&v,seen,&a,&mut ret,prev,p,n);
	ret.sort();
	// for &i in &ret {
	// 	println!("{} {} {} {}", i.0, i.1, i.2, i.3);
	// }
	if ret.len()==0 {
		println!("-1");
		return;
	}
	for &i in &ans {
		print!("{} ", i+1);
	}
	if v.len()==2 {
		print!("{} {}", ret[0].0, ret[0].1);
	}
	if v.len()==3 {
		print!("{} {} {}", ret[0].0, ret[0].1, ret[0].2);
	}
	if v.len()==4 {
		print!("{} {} {} {}", ret[0].0, ret[0].1, ret[0].2, ret[0].3);
	}
}

fn search(v: &Vec<usize>, mut seen: Vec<bool>, a: &[usize], mut ans: &mut Vec<(usize,usize,usize,usize)>, prev: usize, mut p: Vec<usize>, n: usize) {
	// println!("{} {} {}", v.len(), prev, p.len());
	if p.len()==v.len() {
		if p.len()==2 {ans.push((p[0],p[1],n,n));}
		if p.len()==3 {ans.push((p[0],p[1],p[2],n));}
		if p.len()==4 {ans.push((p[0],p[1],p[2],p[3]));}
		return;
	}
	for i in 0..v.len() {
		if seen[i] {continue;}
		let val = v[i];
		if val==prev {
			continue;
		}
		let mut seen_c = seen.clone();
		seen_c[i] = true;
		let mut p_c = p.clone();
		p_c.push(val+1);
		search(&v, seen_c, &a, &mut ans, a[val], p_c, n);
	}
}

fn run() {
    solve();
}

