const MOD: i64 = 1000000007;

fn powmod(a: i64, p: i64, m: i64) -> i64 {
    let mut ret = 1i64;
    let mut aa = a;
    let mut pp = p;
    while pp >= 1 {
        if pp & 1 == 1 {
            ret *= aa;
            ret %= m;
        }
        aa = aa * aa % m;
        pp >>= 1;
    }
    ret
}


fn main() {
    let (n, a, b, c, d): (usize, usize, usize, usize, usize) = read();

    let mut comb: Vec<Vec<i64>> = vec![vec![0; n+1]; n+1];
    for i in 0..(n+1) {
        comb[i][0] = 1;
        comb[i][i] = 1;
        for j in 1..i {
            comb[i][j] = comb[i-1][j-1] + comb[i-1][j];
            comb[i][j] %= MOD;
        }
    }

    let mut invfact: Vec<i64> = vec![0; n+1];
    invfact[0] = 1;

    let mut fact: i64 = 1;
    for i in 1..(n+1) {
        fact = fact * i as i64 % MOD;
        invfact[i] = powmod(fact, MOD-2, MOD);
    }


    let mut dp: Vec<Vec<i64>> = vec![vec![0; n+1]; n+1];
    dp[0][0] = 1;

    let diff = b - a;
    for g in 0..(diff+1) {
        let per = a + g;
        for i in 0..(n+1) {
            let base = dp[g][i];
            if base == 0 {
                continue;
            }
            dp[g+1][i] += base;
            dp[g+1][i] %= MOD;

            let mut left = n - i;
            let mut way: i64 = 1;
            for cnt in 1..(d+1) {
                let to = i + per * cnt;
                if to > n {
                    break;
                }

                way *= comb[left][per];
                way %= MOD;
                left -= per;

                if c <= cnt {
                    dp[g+1][to] += base * way % MOD * invfact[cnt] % MOD;
                    dp[g+1][to] %= MOD;
                }
            }
        }
    }
    println!("{:?}", dp[diff+1][n]);
}

