fn solve(g: Vec<Vec<usize>>, a: Vec<i64>) -> bool {
    let n = g.len();
    if n == 2 {
        return a[0] == a[1];
    }

    let mut root = 0;
    for i in 0..n {
        if g[i].len() >= 2 {
            root = i;
            break;
        }
    }
    let (count, parent, order) = dfs_cpo(&g, root);


    let mut isvalid = true;
    let mut up = vec![0; n];
    for i in 0..n {
        let v = order[i];
        let mut total = 0;
        let mut upmax = 0;
        let mut cn = 0;
        for &to in &g[v] {
            if Some(to) == parent[v] {
                continue;
            }
            total += up[to];
            upmax = max(upmax, up[to]);
            cn += 1;
        }
        if cn == 0 {
            up[v] = a[v];
        } else {
            let maxtie = min(total-upmax, total/2);
