    let ans = if (0..N).all(|i| X[i] <= Y[i].0)
        && (P.iter().collect::<std::collections::HashSet<_>>().len() < N || uft.size(0) < N as i64)
    {
        "Yes"
    } else {
        "No"
    };
    println!("{}", ans);
}

