fn func(a: &Vec<usize>, b: &Vec<usize>, n: usize, m: usize) -> u64 {
    let mut p = vec![false; n*m];
    let mut q = vec![false; n*m];

    for i in 0..n {
        let tar = a[i]-1;
        if p[tar] {
            eprintln!("double row at {}: {}", tar, i);
            return 0;
        }
        p[tar] = true;
    }
    for i in 0..m {
        let tar = b[i]-1;
        if q[tar] {
            eprintln!("double line at {}: {}", tar, i);
            return 0;
        }
        q[tar] = true;
    }
    let mut row = 0;
    let mut line = 0;
    let mut ans = 1;
    let mut tar = n*m-1;
    let mut used = 0;

    while row < n || line < m {
        if p[tar] && q[tar] {
            row += 1;
            line += 1;
            used += 1;
        } else if p[tar] {
            ans *= line as u64;
            ans %= MOD;
            row += 1;
            used += 1;
        } else if q[tar] {
            ans *= row as u64;
            ans %= MOD;
            line += 1;
            used += 1;
        } else {
            if row * line > used {
                ans *= (row * line - used) as u64;
                ans %= MOD;
                used += 1;
            } else {
                eprintln!("empty for {}", tar);
                return 0;
            }
        }
        tar-= 1;
    }

    for i in 0..n*m-used {
        ans *= (i+1) as u64;
        ans %= MOD;
    }

    ans
}

