const P: usize = 1_000_000_000 + 7;

fn dfs_size(
  g: &Vec<Vec<usize>>,
  size: &mut Vec<usize>,
  i: usize,
  used: &mut Vec<bool>,
) {
  used[i] = true;
  size[i] = 1;
  for v in g[i].iter() {
    if used[*v] {
      continue;
    }
    dfs_size(g, size, *v, used);
    size[i] += size[*v];
  }
}

fn dfs_solve(
  g: &Vec<Vec<usize>>,
  used: &mut Vec<bool>,
  size: &Vec<usize>,
  i: usize,
  pair_count: &Vec<usize>,
) -> Vec<[usize; 2]> {
  used[i] = true;
  let mut ret = vec![[0; 2]; 2];
  ret[1][0] = 1;
  let mut current_size = 1;
  for v in g[i].iter() {
    if used[*v] {
      continue;
    }
    let c = dfs_solve(g, used, size, *v, pair_count);
    let mut tmp = vec![[0; 2]; current_size + size[*v] + 1];
    for x in 1..current_size + 1 {
      for y in 1..size[*v] + 1 {
        for m1 in 0..2 {
          for m2 in 0..2 {
            tmp[x + y][(m1 + m2) % 2] += (ret[x][m1] * c[y][m2]) % P;
            tmp[x + y][(m1 + m2) % 2] %= P;
            tmp[x][(m1 + m2 + 1) % 2] +=
              (((ret[x][m1] * pair_count[y]) % P) * c[y][m2]) % P;
            tmp[x][(m1 + m2 + 1) % 2] %= P;
          }
        }
      }
    }
    ret = tmp;
    current_size += size[*v];
  }
  ret
}

fn main() {
  // pray for AC
  input!{
    n: usize,
    xy: [[usize; 2]; n-1],
  };
  let xy: Vec<_> = xy
    .into_iter()
    .map(|xyi| vec![xyi[0] - 1, xyi[1] - 1])
    .collect();
  let mut g = vec![vec![]; n];
  for xyi in xy.iter() {
    let x = xyi[0];
    let y = xyi[1];
    g[x].push(y);
    g[y].push(x);
  }

  let mut size = vec![0; n];
  dfs_size(&g, &mut size, 0, &mut vec![false; n]);

  //let mut dp = vec![vec![vec![0; 2]; n + 1]; n];
  let mut pair_count = vec![0; 5001];
  pair_count[0] = 1;
  for i in 2..5001 {
    if i % 2 == 1 {
      continue;
    }
    pair_count[i] = (pair_count[i - 2] * (i - 1)) % P;
  }
  let dp = dfs_solve(&g, &mut vec![false; n], &size, 0, &pair_count);

  let mut ans = 0;
  for s in 1..size[0] + 1 {
    ans += ((dp[s][0] * pair_count[s]) % P
      + (P - ((dp[s][1] * pair_count[s]) % P)))
      % P;
    ans %= P;
  }
  println!("{}", ans);
}

