        s2 = s1 - 3 * (t_el) + 3

        r1[i:i+t_el] = range(s1, s1 - t_el, -1)
        r2[i:i+t_el] = range(s2, s2 + t_el)

    for i, t_el in zip(range(e // 2 - 1), range(e - 2, 1, -2)):
        s1 = t_el ** 2 + 1
        s2 = s1 + t_el * 3 + 1
        for c, n1, n2 in zip(sg[i+1:i+1+t_el], range(s1, s1 + t_el),
                             range(s2, s2 - t_el, -1)):
            c[i] = n1
            c[i+t_el+1] = n2

