            if m <= i_sm ** 2 + i_sm:
                b = mid + h_i_sm - 1
            else:
                b = mid + h_i_sm

        # optimize square grid
        t_sg = [x[l:r+1] for x in sg[s_r:b + 1]]

        c1 = s_c - l
        for i, x in zip(range(c1, 0, -1), t_sg):
            x[:i] = [0] * i
        c2 = r - s_c
        for i, x in zip(range(c2, 0, -1), t_sg):
