fn check(a0: i32, a1: i32, s: &Vec<char>) -> Option<Vec<i32>> {
    let n = s.len();
    let mut ans = vec![0; n];
    ans[0] = a0;
    ans[1] = a1;
    for i in 1..n-1 {
        match (s[i], ans[i]) {
            ('o', -1) => ans[i+1] = ans[i-1],
            ('x', -1) => ans[i+1] = -ans[i-1],
            ('o', 1) => ans[i+1] = -ans[i-1],
            _ => ans[i+1] = ans[i-1]
        }
    }
    let is_ok = match (s[n-1], ans[n-1]) {
        ('o', -1) => {
            ans[0] == ans[n-2]
        },
        ('x', -1) => {
            ans[0] != ans[n-2]
        },
        ('o', 1) => {
            ans[0] != ans[n-2]
        },
        _ => {
            ans[0] == ans[n-2]
        }
    };
    if is_ok {Some(ans)} else {None}
}

