fn solve(x: Vec<u64>, all: u64) -> u64 {
    let n = x.len();
    if n == 1 {
        return x[0];
    }
    let mut ldsum = 0;
    let mut rdsum = 0;
    let mut left = vec![];
    let mut right = vec![];
    {
        let mut l = 0;
        let mut r = n - 1;
        while l <= r {
            left.push(x[l]);
            ldsum += x[l];
            if l != r {
                right.push(x[r]);
                rdsum += all - x[r];
            }
            l += 1;
            r -= 1;
        }
    }
    let mut ans = 0;

    let mut rt = right.len();
    for lh in 0..n {
        if lh >= 1 {
            ldsum -= left[lh - 1];
        }
        let mut lcnt = left.len() - lh;
        let mut rcnt = rt;
        if lcnt < rcnt {
            left.push(right[rt - 1]);
            rdsum -= all - right[rt - 1];
            ldsum += right[rt - 1];
            rt -= 1;
            lcnt += 1;
            rcnt -= 1;
        }
        let mut distances = 0;
        if lcnt == rcnt {
            // last = R
            distances += (ldsum + rdsum) * 2;
            distances -= all - right[rt - 1];
        } else if lcnt == rcnt + 1 {
            // last = L
            distances += (ldsum + rdsum) * 2;
            let ll = left.len();
            distances -= left[ll - 1];
        } else {
            panic!("arien");
        }
        ans = max(ans, distances);
    }
    ans
}

fn main() {
    input! {
        l: u64, n: usize,
        x: [u64; n]
    };

    let mut revx = vec![0; n];
    for i in 0..n {
        revx[i] = l - x[n - 1 - i];
    }

    let ans = max(solve(x, l), solve(revx, l));
    println!("{}", ans);
}

