struct Solver {
    n: usize,
    a: Vec<i64>,
    cnt: Vec<u32>,
}

impl Solver {
    fn solve(&mut self, p: usize) -> i64 {
        if p*3 > self.n {
            let n = self.n;
            let mut cnt = self.cnt.clone();
            for i in p..self.n {
                let mut j = i;
                let mut sum = 0;
                while j <= self.n {
                    if cnt[j-1] == 0{
                        sum += self.a[j-1];
                    }
                    j += i;
                }
                if sum < 0 {
                    let mut j = i;
                    while j <= self.n {
                        cnt[j-1] += 1;
                        j += i;
                    }
                }
            }
            let res = (0..self.n).filter(|x| cnt[*x] == 0).map(|x| self.a[x]).sum();
            res
        } else {
            let mut ret = self.solve(p+1);
            if self.cnt[p-1] == 0 {
                let mut j = p;
                while j <= self.n {
                    self.cnt[j-1] += 1;
                    j += p;
                }
                ret = std::cmp::max(ret, self.solve(p+1));
                j = p;
                while j <= self.n {
                    self.cnt[j-1] -= 1;
                    j += p;
                }
            }
            ret
        }
    }
}

fn main() {
    let n = readl!(usize);
    let a = readlvec!(i64);
    let mut solver = Solver {n: n, a: a, cnt: vec![0;n]};
    debug!(solver.solve(1));
    println!("{}", solver.solve(1));
}

