fn dijkstra(graph: &[Vec<(i64, usize)>], s: usize) -> Vec<i64> {
    let n = graph.len();
    let mut d = vec![1i64 << 60; n];
    d[s] = 0;
    let mut heap = std::collections::BinaryHeap::new();
    heap.push(Rev((0, s)));
    while let Some(Rev((p_cost, p))) = heap.pop() {
        if d[p] < p_cost {
            continue;
        }
        for &(v_cost, v) in &graph[p] {
            if d[v] > d[p] + v_cost {
                d[v] = d[p] + v_cost;
                heap.push(Rev((d[v], v)));
            }
        }
    }
    d
}

