fn bfs01(src: usize, adj: &[Vec<(usize, usize)>]) -> usize {
    let mut used = vec![false; adj.len()];
    let mut deque = VecDeque::new();
    deque.push_front((src, 1));
    used[src] = true;
    while deque.len() > 0 {
        let (crt, cost) = deque.pop_front().unwrap();
        if used[crt] {
            continue;
        }
        used[crt] = true;
        if crt == 0 {
            return cost;
        }
        for &(nxt, c) in adj[crt].iter() {
            if used[nxt] {
                continue;
            }
            if c == 0 {
                deque.push_front((nxt, cost));
                used[nxt] = true;
            } else {
                deque.push_back((nxt, cost + 1));
            }
            used[nxt] = true;
        }
    }
    0
}

