macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (h, w): (usize, usize) = parse!(it, 2);
    let mut a = vec![];
    let mut b = vec![];
    for _ in 0..h {
        let ai: Vec<usize> = parse!(it, w);
        a.push(ai)
    }
    for _ in 0..h {
        let ai: Vec<usize> = parse!(it, w);
        b.push(ai)
    }

    let M = 15000;
    let mut dp = vec![vec![vec![false; M]; w]; h];
    let diff = |x, y| if x > y { x - y } else { y - x };
    dp[0][0][diff(a[0][0], b[0][0])] = true;
    for i in 0..h {
        for j in 0..w {
            for k in 0..M {
                if !dp[i][j][k] {
                    continue;
                }
                if i < h - 1 {
                    let d = diff(a[i + 1][j], b[i + 1][j]);
                    let dm = diff(k, d);
                    dp[i + 1][j][dm] = true;
                    let dk = k + d;
                    if dk < M {
                        dp[i + 1][j][dk] = true;
                    }
                }
                if j < w - 1 {
                    let d = diff(a[i][j + 1], b[i][j + 1]);
                    let dm = diff(k, d);
                    dp[i][j + 1][dm] = true;
                    let dk = k + d;
                    if dk < M {
                        dp[i][j + 1][dk] = true;
                    }
                }
            }
        }
    }
    for i in 0..M {
        if dp[h - 1][w - 1][i] {
            println!("{}", i);
            return;
        }
    }
}

