macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (n, _): (usize, usize) = parse!(it, 2);
    let a: Vec<_> = parse!(it, n);
    let mut pairs = std::collections::HashMap::new();
    let mut min = std::usize::MAX;
    for i in 0..n {
        if min < a[i] {
            *pairs.entry(a[i] - min).or_insert(0) += 1;
        }
        min = std::cmp::min(min, a[i]);
    }
    let mut max = 0;
    let mut ret = 0;
    for (k, v) in pairs {
        if max < k {
            ret = v;
            max = k;
        }
    }
    println!("{}", ret);
}

