  let ss = group_by(&s,|x,y|x==y);
  let dx = if ss[0][0]=='F' {ss[0].len() as isize} else {0};

  let mut axis_x = true;
  let mut xs = HashSet::new();
  let mut ys = HashSet::new();
  xs.insert(dx);
  ys.insert(0);

  for s in ss.iter().skip_while(|s|s[0]=='F') {
    let l = s.len() as isize;
