      'F' => {if axis_x {xs = xs.into_iter().flat_map(|k|vec![k-l,k+l]).collect::<HashSet<_>>()}
                   else {ys = ys.into_iter().flat_map(|k|vec![k-l,k+l]).collect::<HashSet<_>>()}},
      'T' => {if l%2==1 {axis_x = !axis_x}},
      _ => unreachable!()
    }
  }

  let ans = if xs.contains(&x) && ys.contains(&y) {"Yes"} else {"No"};
  println!("{}", ans)
}

fn group_by<T: PartialEq + Clone, F>(vec: &Vec<T>, f: F) -> Vec<Vec<T>> where F: Fn(&T, &T) -> bool {
  let l = vec.len();
  let mut gs = vec![];
  let mut g = vec![];
  for i in 0 .. l {
    g.push(vec[i].clone());
    if i < l-1 && !f(&vec[i], &vec[i+1]) {
      gs.push(g.clone());
      g.clear()
    }
  }
  gs.push(g.clone());
  gs
}

